L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "\227\129\169\227\129\134\227\129\151\227\129\166\227\129\167\227\129\153\227\129\139\239\188\159\227\128\128\229\137\175\231\164\190\233\149\183\227\129\175\227\131\159\227\131\138\227\129\149\227\130\147\227\130\146\227\129\130\227\129\190\227\130\138\230\176\151\227\129\171\229\133\165\227\129\163\227\129\166\227\129\170\227\129\132\227\129\168\230\128\157\227\129\163\227\129\166\227\129\132\227\129\190\227\129\151\227\129\159\227\129\140\227\128\130"
