L16_1.m_Talk_SCN = "\228\184\186\228\187\128\228\185\136\239\188\159\230\136\145\228\187\165\228\184\186\229\137\175\230\128\187\228\184\141\229\164\170\229\150\156\230\172\162\231\177\179\229\168\156\227\128\130"
